import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        max_val = -1
        for x in a:
            if x > max_val:
                max_val = x

        # If all elements are equal, no one can eat anyone
        if max_val == a[0]:
            results.append("-1")
            continue

        # Find any element that has max_val and has a neighbor strictly smaller
        ans = -1
        for i in range(n):
            if a[i] == max_val:
                # Check left neighbor
                if i > 0 and a[i-1] < a[i]:
                    ans = i + 1
                    break
                # Check right neighbor
                if i < n - 1 and a[i+1] < a[i]:
                    ans = i + 1
                # Since we found a max element, if it's not at boundaries, 
                # one of the neighbors must be smaller unless all are max.
                # But we already handled the "all equal" case.
                # So if we are here and haven't broken, we continue checking.

        results.append(str(ans))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
